unique-window:
def solve(text):
    longest = 0
    for i in range(len(text)):
        seen = []
        for j in range(i, len(text)):
            if text[j] in seen:
                break
            seen = seen + [text[j]]
            longest = max(longest, j - i + 1)
    return longest

maximum-subarray:
def solve(values):
    if not values:
        return 0
    best = values[0]
    current = values[0]
    for x in values[1:]:
        current = max(x, current + x)
        best = max(best, current)
    return best

min-cover-window:
def solve(text, required):
    if not required:
        return ""
    need = {}
    for ch in required:
        if ch in need:
            need[ch] += 1
        else:
            need[ch] = 1
    answer = ""
    for i in range(len(text)):
        have = {}
        for j in range(i, len(text)):
            ch = text[j]
            if ch in have:
                have[ch] += 1
            else:
                have[ch] = 1
            valid = True
            for key in need:
                if key not in have or have[key] < need[key]:
                    valid = False
                    break
            if valid:
                part = text[i:j+1]
                if not answer or len(part) < len(answer):
                    answer = part
                break
    return answer

nonoverlap-intervals:
def solve(intervals):
    remaining = intervals[:]
    chosen = 0
    last_end = -100000
    for step in range(len(remaining)):
        selected = -1
        for i in range(len(remaining)):
            if selected == -1 or remaining[i][1] < remaining[selected][1]:
                selected = i
        item = remaining[selected]
        remaining = remaining[:selected] + remaining[selected+1:]
        if item[0] >= last_end:
            chosen += 1
            last_end = item[1]
    return chosen

trapped-water:
def solve(heights):
    total = 0
    for i in range(len(heights)):
        left = 0
        right = 0
        for j in range(i+1):
            left = max(left, heights[j])
        for j in range(i, len(heights)):
            right = max(right, heights[j])
        total += min(left,right) - heights[i]
    return total

