common-prefix:
def solve(words):
    if not words:
        return ""
    prefix = ""
    for i in range(len(words[0])):
        value = words[0][i]
        valid = True
        for word in words:
            if i >= len(word) or word[i] != value:
                valid = False
                break
        if not valid:
            break
        prefix += value
    return prefix

subsequence-count:
def solve(text, pattern):
    counts = [0] * (len(pattern)+1)
    counts[0] = 1
    for ch in text:
        for i in range(len(pattern)-1, -1, -1):
            if ch == pattern[i]:
                counts[i+1] += counts[i]
    return counts[len(pattern)]
